/**
 * Audit DB Wrapper
 *
 * Wraps Drizzle db to auto-inject audit fields (createdBy, modifiedBy).
 * Uses lazy context access - context is resolved at execution time when
 * .insert() or .update() is called, not when the wrapper is created.

 *
 * Generated by Quickback Compiler.
 */

/**
 * Wraps a Drizzle db instance to automatically inject audit fields.
 *
 * @param db - The Drizzle database instance to wrap
 * @param getCtx - Lazy function to get the current context with userId
 * @returns Wrapped database that injects createdBy/modifiedBy automatically
 */
export function createAuditDb<T extends object>(
  db: T,
  getCtx: () => { userId?: string; principal?: { actor?: { id?: string } } } | undefined
): T {
  return new Proxy(db, {
    get(target, prop, receiver) {
      const value = Reflect.get(target, prop, receiver);

      if (prop === 'insert') {
        const fn = value as Function;
        return (table: any) => wrapInsertBuilder(fn.call(target, table), getCtx);
      }
      if (prop === 'update') {
        const fn = value as Function;
        return (table: any) => wrapUpdateBuilder(fn.call(target, table), getCtx);
      }
      if (prop === 'transaction') {
        const fn = value as Function;
        return (cb: Function, ...rest: any[]) =>
          fn.call(target, (tx: any) => cb(createAuditDb(tx, getCtx)), ...rest);
      }
      return typeof value === 'function' ? value.bind(target) : value;
    },
  }) as T;
}

/**
 * Resolve the writer userId for audit injection. Fails closed when the
 * surrounding request has no user — every write path in generated routes
 * runs after the auth middleware sets ctx.userId, so a missing value here
 * means auth failed silently or the wrapper is being driven from an
 * unauthenticated path that should not be writing to features tables.
 * The one anonymous exception is the PUBLIC write lane (null actor), which
 * only a route whose own access admits PUBLIC can open.
 *
 * If you need to write outside a request (cron, queue handler, seed
 * script), use the unwrapped db (createDb) directly instead of routing
 * through createAuditDb with no context.
 */
function resolveAuditUserId(getCtx: () => any, op: 'insert' | 'update'): string | null {
  const ctx = getCtx();
  const userId = ctx?.userId;
  if (typeof userId === 'string' && userId.length > 0) return userId;
  // Delegated-principal write lane: preserve the resolved actor identity
  // without synthesizing a Better Auth userId. This value came from the
  // compiler-owned credential lookup, never request input.
  const principalActorId = ctx?.principal?.actor?.id;
  if (typeof principalActorId === 'string' && principalActorId.length > 0) {
    return ctx.principal.actor.type + ':' + principalActorId;
  }
  // acceptScope write companion (v0.48+): a VERIFIED scope-only principal has no
  // Better Auth account (userId undefined). It only reaches a write past the
  // acceptScope gate + the table's firewall/access, so the audit layer must NOT
  // block it. Stamp the synthetic, audit-only principal id
  // (scope:<kind>:<subjectId>, the token's sub) as the actor — the 'scope:'
  // prefix self-describes the write and NEVER resolves to a real account.
  // FGA share-link principal (plan 031 Q10): same synthetic-actor lane — the
  // link middleware stamps scopeSubject = 'link:<id>'. Never an account id.
  if (ctx?.scopePrincipal === true || (ctx?.authMethod === 'link' && ctx?.link)) {
    const subject = ctx?.scopeSubject;
    if (typeof subject === 'string' && subject.length > 0) return subject;
    // scopePrincipal without a synthetic sub should be impossible (the auth
    // middleware always stamps it) — fall through to fail-closed rather than
    // silently write a null actor.
  }
  // PUBLIC write lane: a route whose OWN access admits PUBLIC marks an
  // anonymous request (`ctx.__qbPublicWrite`, worker-set after the auth
  // gate, never request input). That caller has no actor, so the audit
  // columns record none — null, never a synthesized id. An authenticated
  // caller never takes this lane: a session with no resolvable identity
  // still fails closed below, as does every route that does not admit PUBLIC.
  if (ctx?.__qbPublicWrite === true && ctx?.authenticated !== true) return null;
  throw new Error(
    'audit-wrapper: ' + op + ' reached without ctx.userId. ' +
    'This indicates an unauthenticated write or auth-context loss. ' +
    'If this is an intentional system-side write, use the unwrapped db directly.'
  );
}

/**
 * Audit columns for a write made through the RAW db handle.
 *
 * createAuditDb() stamps automatically, but it only wraps the scoped `db`
 * injected into actions. A handle built directly from createDb() bypasses it
 * — the documented escape hatch for system writes, broad reads the scoped
 * wrapper over-narrows, and sessionless principals. Those writes still land
 * in audit-managed tables, and the managed columns carry a DDL default of
 * the unix epoch (needed so ALTER TABLE ADD COLUMN works on populated
 * tables). So an omitted column does not fail loudly on NOT NULL any more:
 * it silently persists 1970-01-01T00:00:00.000Z, which reads as a real
 * value everywhere downstream.
 *
 * Spread this instead of hand-writing four columns at every call site:
 *
 *   await db.insert(invoices).values({ ...auditStamp(ctx), amount, orgId });
 *   await db.update(invoices).set({ ...auditStamp(ctx, 'update'), status });
 *
 * Same actor resolution as the wrapper, including the delegated-principal
 * and `scope:<kind>:<subjectId>` lanes, and the same fail-closed throw when
 * no identity is present — a raw-handle write is not a licence to write an
 * anonymous audit row. (Inside an operation whose access admits PUBLIC, an
 * anonymous caller stamps null actors here exactly as the wrapper does.) For genuinely context-free writes (cron, seed,
 * migration) pass your own values; do not reach for this.
 */
export function auditStamp(ctx: any, op: 'insert' | 'update' = 'insert') {
  const userId = resolveAuditUserId(() => ctx, op);
  const now = new Date().toISOString();
  return op === 'insert'
    ? { createdAt: now, createdBy: userId, modifiedAt: now, modifiedBy: userId }
    : { modifiedAt: now, modifiedBy: userId };
}

/**
 * Wrap insert builder to inject createdAt/By and modifiedAt/By.
 *
 * Hard stamp — wrapper always wins. The audit log reflects the actual
 * caller (ctx.userId) and the actual moment (now), and cannot be
 * forged or echoed back through the request body. Migration/import
 * scripts that need to preserve historical timestamps must bypass the
 * wrapper and use the unwrapped db (createDb) directly.
 */
function wrapInsertBuilder(builder: any, getCtx: () => any) {
  return new Proxy(builder, {
    get(target, prop) {
      const value = Reflect.get(target, prop);
      if (prop === 'values') {
        return (data: any) => {
          const userId = resolveAuditUserId(getCtx, 'insert');
          const now = new Date().toISOString();
          const enrich = (item: any) => ({
            ...item,
            createdAt: now,
            createdBy: userId,
            modifiedAt: now,
            modifiedBy: userId,
          });
          return wrapInsertConflict(value.call(target, Array.isArray(data) ? data.map(enrich) : enrich(data)), now, userId);
        };
      }
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });
}

/**
 * Wrap the builder returned by `insert().values()` so a chained
 * `onConflictDoUpdate({ set })` clause receives the same hard audit stamp the
 * `.values()`/`.set()` proxies apply. The conflict branch is the UPDATE half
 * of an upsert, so it stamps modifiedAt/By (never createdAt) with the SAME
 * dialect-correct `now` and `userId` the insert used — upserts audit like
 * every other write and the author never hand-stamps. The stamp OVERRIDES any
 * caller-supplied audit keys (hard-stamp contract). Every other method is
 * forwarded untouched, so `.returning()`, `.onConflictDoNothing()`, thenable
 * adoption, and (when active) the result-tap re-wrapping all behave as before.
 */
function wrapInsertConflict(builder: any, now: any, userId: string | null) {
  // Drizzle's insert chain (.returning(), .onConflictDoNothing(), …) returns
  // the builder itself. Hand back THIS proxy then, not the raw builder: a
  // wrapper above (the scoped db's firewall-on-write gate, realtime capture)
  // keeps the chain only while it gets back what it wrapped (031-F).
  const proxy: any = new Proxy(builder, {
    get(target, prop) {
      const value = Reflect.get(target, prop);
      if (prop === 'onConflictDoUpdate') {
        return (config: any) => {
          if (config && config.set && typeof config.set === 'object') {
            config = { ...config, set: { ...config.set, modifiedAt: now, modifiedBy: userId } };
          }
          const result = value.call(target, config);
          return result === target ? proxy : result;
        };
      }
      if (typeof value !== 'function') return value;
      return (...args: any[]) => {
        const result = value.apply(target, args);
        return result === target ? proxy : result;
      };
    },
  });
  return proxy;
}

/**
 * Wrap update builder to inject modifiedAt/By (and deletedAt/By for
 * soft delete).
 *
 * Hard stamp — same contract as the insert path. Caller-supplied
 * audit fields are dropped on the floor; the wrapper writes the real
 * actor and the real moment. The escape hatch for intentional
 * preservation is the unwrapped db (createDb) directly.
 *
 * Soft delete: a caller signals intent by passing deletedAt in the
 * .set() payload (any value). The wrapper normalizes the actual
 * stored value to now / ctx.userId.
 */
function wrapUpdateBuilder(builder: any, getCtx: () => any) {
  return new Proxy(builder, {
    get(target, prop) {
      const value = Reflect.get(target, prop);
      if (prop === 'set') {
        return (data: any) => {
          const userId = resolveAuditUserId(getCtx, 'update');
          const now = new Date().toISOString();
          const enriched = {
            ...data,
            modifiedAt: now,
            modifiedBy: userId,
          };
          if (data.deletedAt !== undefined) {
            enriched.deletedAt = now;
            enriched.deletedBy = userId;
          }
          return value.call(target, enriched);
        };
      }
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });
}

